begin;
select plan(35);
insert into auth.users(id) values ('5b000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values ('6b000000-0000-4000-8000-000000000001','5b000000-0000-4000-8000-000000000001');
insert into public.staff_members(user_id,active,display_name) values ('5b000000-0000-4000-8000-000000000001',true,'Equipe revisão');
insert into public.animals(id,name,species,sex,size,approximate_age) values ('7b000000-0000-4000-8000-000000000001','Fixture revisão','dog','female','small','2');
create temporary table revision_test(kind text,value jsonb);grant all on revision_test to authenticated;
select set_config('request.jwt.claims','{"sub":"5b000000-0000-4000-8000-000000000001","session_id":"6b000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
insert into revision_test select 'saved',public.save_medication_treatment(repeat('A',32),'{"animal_id":"7b000000-0000-4000-8000-000000000001","medication_name":"Original","schedule_mode":"fixed_times","starts_on":"2020-01-01","starts_time":"08:00","ends_on":"2020-01-01","ends_time":"20:00","fixed_times":["08:00","09:00","10:00","11:00"]}');
reset role;
with ordered as(select id,row_number() over(order by scheduled_at) n from public.medication_applications where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved'))
update public.medication_applications a set scheduled_at=clock_timestamp()+case when n=1 then interval '-2 hours' when n=2 then interval '-1 hour' when n=3 then interval '1 hour' else interval '2 hours' end from ordered o where a.id=o.id;
insert into revision_test select 'old',jsonb_agg(jsonb_build_object('id',id,'at',scheduled_at) order by scheduled_at) from public.medication_applications where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved');
insert into revision_test select 'edit_payload',jsonb_build_object('treatment_id',(select value#>>'{result,treatment,id}' from revision_test where kind='saved'),'animal_id','7b000000-0000-4000-8000-000000000001','expected_revision',1,'expected_treatment_version',1,'medication_name','Revisado','schedule_mode','fixed_times','starts_on',to_char(clock_timestamp() at time zone 'America/Sao_Paulo','YYYY-MM-DD'),'starts_time','00:00','ends_on',to_char((clock_timestamp() at time zone 'America/Sao_Paulo')::date+1,'YYYY-MM-DD'),'ends_time','23:59','fixed_times',jsonb_build_array('08:00','20:00'));
set local role authenticated;
insert into revision_test select 'done',public.complete_medication_application(repeat('B',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),1);
insert into revision_test select 'edited',public.save_medication_treatment(repeat('C',32),(select value from revision_test where kind='edit_payload'));
select is((select (value#>>'{result,treatment,revision}')::int from revision_test where kind='edited'),2,'edit creates immutable new revision');
select is((select (value#>>'{result,treatment,version}')::int from revision_test where kind='edited'),2,'treatment version increments independently');
select is((select (value#>>'{result,cancelled_count}')::int from revision_test where kind='edited'),2,'only two future pending applications cancelled');
select is((select state from public.medication_applications where id=(select (value->1->>'id')::uuid from revision_test where kind='old')),'pending','overdue pending preserved');
select is((select state from public.medication_applications where id=(select (value->0->>'id')::uuid from revision_test where kind='old')),'completed','completed preserved');
select is((select count(*)::int from public.medication_treatment_revisions where treatment_id=(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved')),2,'both programming revisions retained');
select ok(not exists(select 1 from public.medication_applications where revision=2 and treatment_id=(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved') and scheduled_at<=(select (value->>'server_now')::timestamptz from revision_test where kind='edited')),'new revision generates only strictly future instants');
select ok(not exists(select 1 from public.medication_applications where state in('pending','completed') and treatment_id=(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved') group by treatment_id,scheduled_at having count(*)>1),'no active duplicate at same instant');
select is(public.save_medication_treatment(repeat('C',32),(select value from revision_test where kind='edit_payload')),(select value from revision_test where kind='edited'),'edit replay preserves receipt');
select throws_ok($$select public.save_medication_treatment(repeat('D',32),(select value from revision_test where kind='edit_payload'))$$,'PT409','stale_version','stale edit denied');
insert into revision_test select 'stopped',public.stop_medication_treatment(repeat('E',32),(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved'),2,2);
select is((select value#>>'{result,treatment,status}' from revision_test where kind='stopped'),'stopped','stop confirmed');
select is((select (value#>>'{result,treatment,revision}')::int from revision_test where kind='stopped'),2,'stop does not invent a programming revision');
select is((select (value#>>'{result,treatment,version}')::int from revision_test where kind='stopped'),3,'stop increments treatment version');
select is((select state from public.medication_applications where id=(select (value->1->>'id')::uuid from revision_test where kind='old')),'pending','stop keeps overdue application visible');
select throws_ok($$select public.stop_medication_treatment(repeat('F',32),(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved'),2,2)$$,'PT409','stale_version','stale stop denied');
reset role;
insert into revision_test select 'counter',to_jsonb(agenda_version) from private.medication_agenda_state;
set local role authenticated;
insert into revision_test select 'stop_again',public.stop_medication_treatment(repeat('G',32),(select (value#>>'{result,treatment,id}')::uuid from revision_test where kind='saved'),2,3);
select is((select (value#>>'{result,treatment,version}')::int from revision_test where kind='stop_again'),3,'already stopped remains same version');
reset role;
select is((select agenda_version from private.medication_agenda_state),(select value::text::bigint from revision_test where kind='counter'),'no-op stop does not change agenda snapshot');
set local role authenticated;
select throws_ok($$select public.save_medication_treatment(repeat('H',32),(select value||'{"expected_revision":2,"expected_treatment_version":3}'::jsonb from revision_test where kind='edit_payload'))$$,'PT409','treatment_stopped','stopped treatment cannot be edited/reactivated');
select lives_ok($$select public.complete_medication_application(repeat('I',32),(select (value->1->>'id')::uuid from revision_test where kind='old'),1)$$,'overdue application remains resolvable after stop');
select throws_ok($$select public.reverse_medication_completion(repeat('J',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),2,'   ')$$,'22023','invalid_payload','blank correction reason denied');
select throws_ok($$select public.reverse_medication_completion(repeat('J',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),2,repeat('x',501))$$,'22023','invalid_payload','501 characters denied');
insert into revision_test select 'reversed',public.reverse_medication_completion(repeat('K',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),2,repeat('é',500));
select is((select value#>>'{result,application,state}' from revision_test where kind='reversed'),'pending','correction returns to pending');
select ok((select value#>>'{result,application,performed_by}' is null and value#>>'{result,application,performed_at}' is null from revision_test where kind='reversed'),'correction clears current performer fields');
select is((select (value#>>'{result,application,version}')::int from revision_test where kind='reversed'),3,'correction increments application version');
select is((select char_length(value#>>'{result,event,reason}') from revision_test where kind='reversed'),500,'500 Unicode characters accepted');
select is(public.get_medication_application_history((select (value->0->>'id')::uuid from revision_test where kind='old'),null)->'items'->0,(select value#>'{result,event}' from revision_test where kind='done'),'original author/time event immutable after reversal');
select is(public.reverse_medication_completion(repeat('K',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),2,' '||repeat('é',500)||' '),(select value from revision_test where kind='reversed'),'normalized reason replays original correction');
select throws_ok($$select public.reverse_medication_completion(repeat('L',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),2,'x')$$,'PT409','stale_version','stale correction denied');
select throws_ok($$select public.reverse_medication_completion(repeat('L',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),3,'x')$$,'PT409','not_completed','pending cannot be reversed again');
insert into revision_test select 'done_again',public.complete_medication_application(repeat('M',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),3);
select is((select (value#>>'{result,application,version}')::int from revision_test where kind='done_again'),4,'a later completion is a distinct version');
select is(jsonb_array_length(public.get_medication_application_history((select (value->0->>'id')::uuid from revision_test where kind='old'),null)->'items'),3,'completion/correction/new completion all preserved');
select lives_ok($$select public.reverse_medication_completion(repeat('N',32),(select (value->0->>'id')::uuid from revision_test where kind='old'),4,'x')$$,'single character correction reason accepted');
reset role;
select ok((select snapshot->>'performed_by'='5b000000-0000-4000-8000-000000000001' from public.medication_application_events where application_id=(select (value->0->>'id')::uuid from revision_test where kind='old') and event_type='completion_reversed' order by application_version limit 1),'correction snapshot preserves original performer');
set local role anon;
select throws_ok($$select public.reverse_medication_completion(repeat('N',32),'9b000000-0000-4000-8000-000000000001',4,'x')$$,'42501',null,'visitor cannot correct');
select throws_ok($$select public.stop_medication_treatment(repeat('N',32),'8b000000-0000-4000-8000-000000000001',1,1)$$,'42501',null,'visitor cannot stop');
reset role;
select * from finish();rollback;
